const WalkGeom *walkGeomForRoom(int room, uint &count) {
	count = 0;
	for (uint i = 0; i < ARRAYSIZE(kWalkGeomRooms); i++) {
		if (kWalkGeomRooms[i].room != room)
			continue;
		count = kWalkGeomRooms[i].count;
		return &kWalkGeom[kWalkGeomRooms[i].first];
	}
	return nullptr;
}

